import { useCallback, useEffect, useState } from 'react';
import Head from 'next/head';
import { adminFetch, adminMutation, apiErrorMessage } from '@/lib/admin-client';

type Item = { id: string; title_ar: string; image_url: string; deep_link: string };
type Section = { id: string; type: string; title_ar: string; position: number; enabled: boolean; items: Item[] };
type Curation = { key: string; version: number; sections: Section[]; updatedAt?: string | null };
const emptySection = (): Section => ({ id: `section_${Date.now().toString(36)}`, type: 'banner', title_ar: '', position: 0, enabled: true, items: [] });
const emptyItem = (): Item => ({ id: `item_${Date.now().toString(36)}`, title_ar: '', image_url: '', deep_link: '' });

export default function HomeCurationPage() {
  const [curation, setCuration] = useState<Curation>({ key: 'primary', version: 0, sections: [] }); const [reason, setReason] = useState(''); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [error, setError] = useState('');
  const load = useCallback(async () => { setLoading(true); setError(''); try { setCuration(await adminFetch<Curation>('/governance-controls/home-curation')); } catch (cause) { setError(apiErrorMessage(cause, 'تعذر تحميل ترتيب الصفحة الرئيسية.')); } finally { setLoading(false); } }, []);
  useEffect(() => { void load(); }, [load]);
  function setSection(index: number, patch: Partial<Section>) { setCuration((current) => ({ ...current, sections: current.sections.map((section, i) => i === index ? { ...section, ...patch } : section) })); }
  function setItem(sectionIndex: number, itemIndex: number, patch: Partial<Item>) { setCuration((current) => ({ ...current, sections: current.sections.map((section, i) => i === sectionIndex ? { ...section, items: section.items.map((item, j) => j === itemIndex ? { ...item, ...patch } : item) } : section) })); }
  function move(index: number, delta: -1 | 1) { setCuration((current) => { const target = index + delta; if (target < 0 || target >= current.sections.length) return current; const sections = [...current.sections]; [sections[index], sections[target]] = [sections[target], sections[index]]; return { ...current, sections: sections.map((section, position) => ({ ...section, position })) }; }); }
  async function save() { if (reason.trim().length < 5) { setError('سبب الحفظ مطلوب ويتكون من خمسة أحرف على الأقل.'); return; } setSaving(true); setError(''); try { const saved = await adminMutation<Curation>('/governance-controls/home-curation', 'POST', { sections: curation.sections, reason: reason.trim() }); setCuration(saved); setReason(''); } catch (cause) { setError(apiErrorMessage(cause, 'تعذر حفظ ترتيب الصفحة الرئيسية.')); } finally { setSaving(false); } }
  return <><Head><title>ترتيب الصفحة الرئيسية | نبض</title></Head><section dir="rtl" className="space-y-6 p-6 md:p-8"><header><h1 className="text-3xl font-bold">ترتيب الصفحة الرئيسية</h1><p className="mt-1 text-sm text-slate-500">ترتيب الأقسام هنا هو المصدر الخادمي للبانرات والوحدات؛ لا توجد معاينة ببيانات افتراضية.</p></header>{error ? <p role="alert" className="rounded-lg bg-rose-50 p-3 text-rose-700">{error}</p> : null}{loading ? <p className="rounded-2xl border bg-white p-10 text-center text-slate-500">جارٍ تحميل الترتيب…</p> : <><div className="rounded-2xl border bg-white p-5 shadow-sm"><p className="text-sm text-slate-500">الإصدار: {curation.version} · آخر تحديث: {curation.updatedAt ? new Date(curation.updatedAt).toLocaleString('ar-SA') : 'لا يوجد ترتيب منشور بعد'}</p></div><div className="space-y-4">{curation.sections.map((section, index) => <article key={section.id} className="rounded-2xl border bg-white p-5 shadow-sm"><div className="flex flex-wrap items-center justify-between gap-3"><div className="flex gap-2"><button onClick={() => move(index, -1)} disabled={index === 0} className="rounded border px-3 py-1 disabled:opacity-40">أعلى</button><button onClick={() => move(index, 1)} disabled={index === curation.sections.length - 1} className="rounded border px-3 py-1 disabled:opacity-40">أسفل</button></div><button onClick={() => setCuration((current) => ({ ...current, sections: current.sections.filter((_, i) => i !== index).map((item, position) => ({ ...item, position })) }))} className="rounded border border-rose-300 px-3 py-1 text-rose-700">حذف القسم</button></div><div className="mt-4 grid gap-3 md:grid-cols-4"><input value={section.id} onChange={(e) => setSection(index, { id: e.target.value })} className="rounded border p-2 text-sm" placeholder="معرّف القسم"/><input value={section.type} onChange={(e) => setSection(index, { type: e.target.value })} className="rounded border p-2 text-sm" placeholder="النوع"/><input value={section.title_ar} onChange={(e) => setSection(index, { title_ar: e.target.value })} className="rounded border p-2 text-sm" placeholder="العنوان"/><label className="flex items-center gap-2 rounded border px-3 text-sm"><input type="checkbox" checked={section.enabled} onChange={(e) => setSection(index, { enabled: e.target.checked })}/> ظاهر</label></div><div className="mt-4 space-y-2"><h2 className="font-bold">العناصر</h2>{section.items.map((item, itemIndex) => <div key={item.id} className="grid gap-2 rounded bg-slate-50 p-3 md:grid-cols-5"><input value={item.id} onChange={(e) => setItem(index, itemIndex, { id: e.target.value })} className="rounded border p-2 text-sm" placeholder="معرّف"/><input value={item.title_ar} onChange={(e) => setItem(index, itemIndex, { title_ar: e.target.value })} className="rounded border p-2 text-sm" placeholder="العنوان"/><input value={item.image_url} onChange={(e) => setItem(index, itemIndex, { image_url: e.target.value })} dir="ltr" className="rounded border p-2 text-sm" placeholder="رابط الصورة"/><input value={item.deep_link} onChange={(e) => setItem(index, itemIndex, { deep_link: e.target.value })} dir="ltr" className="rounded border p-2 text-sm" placeholder="المسار"/><button onClick={() => setSection(index, { items: section.items.filter((_, i) => i !== itemIndex) })} className="rounded border px-2 text-sm">حذف</button></div>)}<button onClick={() => setSection(index, { items: [...section.items, emptyItem()] })} className="rounded border px-3 py-2 text-sm">إضافة عنصر</button></div></article>)}</div><button onClick={() => setCuration((current) => ({ ...current, sections: [...current.sections, { ...emptySection(), position: current.sections.length }] }))} className="rounded border px-4 py-2 text-sm">إضافة قسم</button><div className="rounded-2xl border bg-white p-5 shadow-sm"><label className="block text-sm font-medium">سبب الحفظ<textarea value={reason} onChange={(e) => setReason(e.target.value)} minLength={5} className="mt-2 min-h-20 w-full rounded-lg border p-2"/></label><button disabled={saving} onClick={() => void save()} className="mt-3 rounded bg-teal-700 px-5 py-2 font-bold text-white disabled:opacity-50">{saving ? 'جارٍ النشر…' : 'حفظ الترتيب وتدقيقه'}</button></div></>}</section></>;
}
